WITH inner_cte AS ( SELECT SPACE_UNIT.SPACE_UNIT AS department_name, AVG(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES) AS avg_supervisees, MAX(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES) - MIN(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES) AS supervisee_range, VARIANCE(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES) AS supervisee_variance FROM SPACE_SUPERVISOR_USAGE JOIN SPACE_UNIT ON SPACE_SUPERVISOR_USAGE.DEPT_NAMES = SPACE_UNIT.DLC_KEY GROUP BY SPACE_UNIT.SPACE_UNIT ) SELECT inner_cte.department_name, inner_cte.avg_supervisees, inner_cte.supervisee_range, inner_cte.supervisee_variance, SUM(SSU.SQFT) AS total_sqft, SUM(SSU.RESEARCH_VOLUME) AS total_research_volume FROM inner_cte JOIN SPACE_UNIT SU ON inner_cte.department_name = SU.SPACE_UNIT JOIN SPACE_SUPERVISOR_USAGE SSU ON SU.DLC_KEY = SSU.DEPT_NAMES GROUP BY inner_cte.department_name, inner_cte.avg_supervisees, inner_cte.supervisee_range, inner_cte.supervisee_variance ORDER BY inner_cte.supervisee_range DESC;